import { test, expect } from '@playwright/test';

test.describe('Modal Dialog Scrolling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.getByRole('button', { name: 'Open Modal' }).click(); // Adjust the button name as necessary
  });

  test('should display modal with scrollable content', async ({ page }) => {
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    const content = modal.locator('.modal-content'); // Adjust the selector based on your modal's content
    await expect(content).toHaveCSS('overflow-y', 'auto');
  });

  test('should scroll modal content independently', async ({ page }) => {
    const modal = page.getByRole('dialog');
    const scrollableContent = modal.locator('.modal-scrollable'); // Adjust the selector based on your modal's scrollable content

    await scrollableContent.evaluate((el) => {
      el.scrollTop = el.scrollHeight; // Scroll to the bottom
    });

    await expect(scrollableContent).toHaveCSS('scrollTop', '100'); // Adjust the expected value based on your content height
  });
});
